package org.xar.ck3.control.nativebridge.capabilities.army;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.NullNode;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;
import org.xar.ck3.control.application.action.RawJson;
import org.xar.ck3.control.contracts.ExactRef;
import org.xar.ck3.control.wave2.military.armyqueue.ArmyDailyQueueInputs;
import static org.xar.ck3.control.nativebridge.capabilities.army.ArmyTypes.*;
import static org.xar.ck3.control.nativebridge.capabilities.army.ArmyStrengthsFamilies.Key;
import static org.xar.ck3.control.nativebridge.capabilities.army.ArmyStrengthsPipeline.Stage;

/** Installs only complete typed contracts and the actual eight pure service stages. */
public final class ArmyStrengthsAssaultInstaller {
    private ArmyStrengthsAssaultInstaller() { }
    record Losses(List<ArmyStrengthsAssaultLoss.Result> values){Losses{values=List.copyOf(values);}}
    record Queues(List<ArmyStrengthsAssaultCurrent.Queue> values){Queues{values=List.copyOf(values);}}
    record Releases(List<ArmyStrengthsAssaultCurrent.Release> values){Releases{values=List.copyOf(values);}}
    record Removals(List<ArmyStrengthsAssaultRemoval.Result> values){Removals{values=List.copyOf(values);}}
    record Groups(List<ArmyStrengthsAssaultCurrent.Groups> values){Groups{values=List.copyOf(values);}}
    record Placements(List<ArmyStrengthsAssaultCurrent.Placement> values){Placements{values=List.copyOf(values);}}
    record Admission(int army,ArmyStrengthsRosterContract.Projection value) { }
    record Admissions(List<Admission> values){Admissions{values=List.copyOf(values);}}
    record Eligible(int army,boolean exact4,BigInteger sequence,boolean observed,List<ArmyStrengthsAssaultEligible.Result> groups){Eligible{groups=List.copyOf(groups);}}
    record Eligibles(List<Eligible> values){Eligibles{values=List.copyOf(values);}}
    static <T> T family(ArmyStrengths.Row row,Key key,Class<T> type){for(var family:row.families())if(family.key()==key){require(family.valueType().equals(type),"Army family lost its exact typed contract: "+key);return family.value() instanceof Present<?> value?type.cast(value.value()):null;}return null;}
    static List<Integer> pending(ArmyStrengths.Row row){ArmyDailyQueueInputs q=family(row,Key.MONTHLY_DAILY_QUEUE_INPUTS_V1,ArmyDailyQueueInputs.class);return q==null?null:q.orderedIds().map(ids->ids.stream().map(ArmyDailyQueueInputs.ArmyId::value).toList()).orElse(null);}
    static void install(ArmyStrengthsFamilies.Registry registry,ArmyStrengthsPipeline pipeline,ExactRef source){
        add(registry,Key.CURRENT_DAILY_ASSAULT_TABLE_V1,ArmyStrengthsAssaultCodec.Table.class,ArmyStrengthsAssaultCodec::decodeTable,ArmyStrengthsAssaultCodec::encodeTable,source);
        add(registry,Key.CURRENT_DAILY_ASSAULT_LOSS_INPUTS_V1,ArmyStrengthsAssaultCodec.LossInputs.class,ArmyStrengthsAssaultCodec::decodeLoss,ArmyStrengthsAssaultCodec::encodeLoss,source);
        add(registry,Key.CURRENT_ASSAULT_REMOVAL_REFERENCE_INPUTS_V1,ArmyStrengthsAssaultRemoval.Inputs.class,ArmyStrengthsAssaultRemoval::decode,ArmyStrengthsAssaultRemoval::encodeInputs,source);
        add(registry,Key.CURRENT_DAILY_ASSAULT_ROSTER_ADMISSION_V1,ArmyStrengthsRosterContract.Root.class,node->ArmyStrengthsRosterContract.decodeRoot(ArmyStrengthsRosterContract.normalizeRoster(node)),ArmyStrengthsRosterContract::encodeRoot,source);
        pipeline.register(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_LOSS_V1,Losses.class,List.of(),(input,earlier)->new Losses(input.selected().stream().map(row->ArmyStrengthsAssaultLoss.project(row.core().army().value(),family(row,Key.CURRENT_DAILY_ASSAULT_TABLE_V1,ArmyStrengthsAssaultCodec.Table.class),family(row,Key.CURRENT_DAILY_ASSAULT_LOSS_INPUTS_V1,ArmyStrengthsAssaultCodec.LossInputs.class))).toList()),ArmyStrengthsAssaultInstaller::losses,value->publicStage(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_LOSS_V1,losses(value)),source);
        pipeline.register(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_QUEUE_APPEND_V1,Queues.class,List.of(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_LOSS_V1),(input,earlier)->{List<ArmyStrengthsAssaultCurrent.Queue> result=new ArrayList<>();var losses=earlier.required(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_LOSS_V1,Losses.class);for(int i=0;i<input.selected().size();i++){var row=input.selected().get(i);result.add(ArmyStrengthsAssaultCurrent.queue(row.core().army().value(),pending(row),losses.values().get(i)));}return new Queues(result);},ArmyStrengthsAssaultInstaller::queues,value->publicStage(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_QUEUE_APPEND_V1,queues(value)),source);
        pipeline.register(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_NORMAL_RETURN_RELEASE_V1,Releases.class,List.of(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_QUEUE_APPEND_V1),(input,earlier)->{List<ArmyStrengthsAssaultCurrent.Release> result=new ArrayList<>();var queues=earlier.required(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_QUEUE_APPEND_V1,Queues.class);for(int i=0;i<input.selected().size();i++){var row=input.selected().get(i);result.add(ArmyStrengthsAssaultCurrent.release(row.core().army().value(),family(row,Key.CURRENT_DAILY_ASSAULT_TABLE_V1,ArmyStrengthsAssaultCodec.Table.class),queues.values().get(i)));}return new Releases(result);},ArmyStrengthsAssaultInstaller::releases,value->publicStage(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_NORMAL_RETURN_RELEASE_V1,releases(value)),source);
        pipeline.register(Stage.SAME_INPUT_CURRENT_ASSAULT_FIRST_REMOVAL_V1,Removals.class,List.of(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_NORMAL_RETURN_RELEASE_V1),(input,earlier)->{List<ArmyStrengthsAssaultRemoval.Result> result=new ArrayList<>();var releases=earlier.required(Stage.SAME_INPUT_CURRENT_DAILY_ASSAULT_NORMAL_RETURN_RELEASE_V1,Releases.class);for(int i=0;i<input.selected().size();i++){var row=input.selected().get(i);result.add(ArmyStrengthsAssaultRemoval.project(row.core().army().value(),family(row,Key.CURRENT_ASSAULT_REMOVAL_REFERENCE_INPUTS_V1,ArmyStrengthsAssaultRemoval.Inputs.class),pending(row),releases.values().get(i)));}return new Removals(result);},ArmyStrengthsAssaultInstaller::removals,value->publicStage(Stage.SAME_INPUT_CURRENT_ASSAULT_FIRST_REMOVAL_V1,removals(value)),source);
        pipeline.register(Stage.CURRENT_DAILY_ASSAULT_GROUP_INPUTS_V1,Groups.class,List.of(),(input,earlier)->new Groups(input.selected().stream().map(row->ArmyStrengthsAssaultCurrent.groups(row.core().army().value(),family(row,Key.CURRENT_DAILY_ASSAULT_TABLE_V1,ArmyStrengthsAssaultCodec.Table.class))).toList()),ArmyStrengthsAssaultInstaller::groups,value->publicStage(Stage.CURRENT_DAILY_ASSAULT_GROUP_INPUTS_V1,groups(value)),source);
        pipeline.register(Stage.CURRENT_DAILY_ASSAULT_PLACEMENT_INPUTS_V1,Placements.class,List.of(),(input,earlier)->new Placements(input.selected().stream().map(row->ArmyStrengthsAssaultCurrent.placement(family(row,Key.CURRENT_DAILY_ASSAULT_TABLE_V1,ArmyStrengthsAssaultCodec.Table.class))).toList()),ArmyStrengthsAssaultInstaller::placements,value->publicStage(Stage.CURRENT_DAILY_ASSAULT_PLACEMENT_INPUTS_V1,placements(value)),source);
        pipeline.register(Stage.CURRENT_DAILY_ASSAULT_ROSTER_ADMISSION_INPUTS_V1,Admissions.class,List.of(),(input,earlier)->new Admissions(input.selected().stream().map(row->new Admission(row.core().army().value(),ArmyStrengthsRosterContract.project(family(row,Key.CURRENT_DAILY_ASSAULT_ROSTER_ADMISSION_V1,ArmyStrengthsRosterContract.Root.class),row.core().army().value()))).toList()),ArmyStrengthsAssaultInstaller::admissions,value->publicStage(Stage.CURRENT_DAILY_ASSAULT_ROSTER_ADMISSION_INPUTS_V1,admissions(value)),source);
        pipeline.register(Stage.SAME_QUERY_CONDITIONAL_ASSAULT_GROUP_CONTRIBUTORS_12004,Eligibles.class,List.of(),(input,earlier)->{
            boolean exact=input.exactNativeBuild("1.20.0.4","98702F88A547CDE2EAF29A85F93B85F68EE4CF8148336A4F7AFAEB75319DD518");List<Eligible> result=new ArrayList<>();for(var row:input.selected()){var family=family(row,Key.CURRENT_DAILY_ASSAULT_LOSS_INPUTS_V1,ArmyStrengthsAssaultCodec.LossInputs.class);List<ArmyStrengthsAssaultEligible.Result> groups=new ArrayList<>();if(exact&&family!=null)for(var group:family.groups()){var ordered=group.ordered() instanceof Present<ArmyStrengthsRefill.OrderedBesieging> p?p.value():null;groups.add(ArmyStrengthsAssaultEligible.project(group,List.of(),ordered));}result.add(new Eligible(row.core().army().value(),exact,input.original().sequence(),family!=null,groups));}return new Eligibles(result);
        },ArmyStrengthsAssaultInstaller::eligibles,value->publicStage(Stage.SAME_QUERY_CONDITIONAL_ASSAULT_GROUP_CONTRIBUTORS_12004,eligibles(value)),source);
    }
    private static <T> void add(ArmyStrengthsFamilies.Registry registry,Key key,Class<T> type,Function<JsonNode,T> decoder,Function<T,JsonNode> encoder,ExactRef source){registry.register(key,type,(actual,row)->actual instanceof Missing<RawJson>?new Missing<>():actual instanceof NullValue<RawJson>?new NullValue<>():new Present<>(decoder.apply(ArmyStrengthsCodec.parseValue(((Present<RawJson>)actual).value()))),value->raw(value instanceof Present<T> p?encoder.apply(p.value()):NullNode.getInstance()),value->publicFamily(key,raw(value instanceof Present<T> p?encoder.apply(p.value()):NullNode.getInstance())),source);}
    static RawJson raw(JsonNode node){return new RawJson(ArmyJson.bytes(node));}
    private static <T> RawJson perArmy(List<T> values,java.util.function.ToIntFunction<T> id,Function<T,JsonNode> encoder){ArrayNode out=ArmyJson.empty().arrayNode();for(T value:values)out.addObject().put("army_id",id.applyAsInt(value)).set("projection",encoder.apply(value));return raw(out);}
    private static RawJson losses(Losses v){return perArmy(v.values(),ArmyStrengthsAssaultLoss.Result::army,ArmyStrengthsAssaultLoss::encode);}
    private static RawJson queues(Queues v){return perArmy(v.values(),ArmyStrengthsAssaultCurrent.Queue::army,ArmyStrengthsAssaultCurrent::encodeQueue);}
    private static RawJson releases(Releases v){return perArmy(v.values(),ArmyStrengthsAssaultCurrent.Release::army,ArmyStrengthsAssaultCurrent::encodeRelease);}
    private static RawJson removals(Removals v){return perArmy(v.values(),ArmyStrengthsAssaultRemoval.Result::army,ArmyStrengthsAssaultRemoval::encode);}
    private static RawJson groups(Groups v){ArrayNode out=ArmyJson.empty().arrayNode();v.values().forEach(g->out.add(ArmyStrengthsAssaultCurrent.encodeGroups(g)));return raw(out);}
    private static RawJson placements(Placements v){ArrayNode out=ArmyJson.empty().arrayNode();v.values().forEach(p->out.add(ArmyStrengthsAssaultCurrent.encodePlacement(p)));return raw(out);}
    private static RawJson admissions(Admissions v){return perArmy(v.values(),Admission::army,a->ArmyStrengthsRosterContract.encodeProjection(a.value()));}
    private static RawJson eligibles(Eligibles v){return perArmy(v.values(),Eligible::army,e->{var out=ArmyJson.empty().put("source_contract_game_version","1.20.0.4").put("input_basis","same_query_current_physical_values; conditional_group_refresh_only").put("query_sequence",e.sequence()).putNull("capture_id").put("actual_stage_entry_observed",false).put("status",e.exact4()&&e.observed()&&e.groups().stream().allMatch(ArmyStrengthsAssaultEligible.Result::ready)?"available":e.exact4()&&e.observed()?"partial":"unavailable").put("original_native_scalars_preserved",true).put("actual_loss",false).put("actual_effects",false).put("full_daily_assault_ready",false).put("full_monthly_ready",false);ArrayNode groups=out.putArray("group_budget_outputs");e.groups().forEach(g->groups.add(ArmyStrengthsAssaultEligible.encode(g)));ArrayNode missing=out.putArray("missing_inputs");if(!e.exact4())missing.add("exact_actual4_query_source");else if(!e.observed())missing.add("current_daily_assault_loss_inputs_v1");return out;});}
    static RawJson publicFamily(Key key,RawJson input){return ArmyStrengthsPublicNumbers.encode(input,familyRules(key));}
    static List<ArmyStrengthsPublicNumbers.Rule> familyRules(Key key){List<ArmyStrengthsPublicNumbers.Rule> rules=new ArrayList<>();switch(key){
        case CURRENT_DAILY_ASSAULT_TABLE_V1->{signed(rules,"/physical_controls/*/physical_slot_i64","/groups/*/physical_slot_i64");}
        case CURRENT_DAILY_ASSAULT_LOSS_INPUTS_V1->{signed(rules,"/groups/*/physical_slot_i64","/groups/*/besieging_inputs_v1/assault_context/casualty_percentage_raw","/groups/*/ordered_besieging_refill_inputs_v1/persistent_regiments/*/prepared_fraction_raw");dataRules(rules,"/target_regiments/*/replenishment_records_v1");dataRules(rules,"/groups/*/besieging_inputs_v1/occurrences/*/regiments/*/replenishment_records_v1");}
        case CURRENT_ASSAULT_REMOVAL_REFERENCE_INPUTS_V1->signed(rules,"/reference_occurrences/*/group_physical_slot_i64");
        case CURRENT_DAILY_ASSAULT_ROSTER_ADMISSION_V1->rosterRules(rules,"");
        default->throw new IllegalArgumentException("not an ASSAULT family");
    }return List.copyOf(rules);}
    static void signed(List<ArmyStrengthsPublicNumbers.Rule> rules,String... paths){for(String path:paths)rules.add(new ArmyStrengthsPublicNumbers.Rule(path,ArmyStrengthsPublicNumbers.Domain.SIGNED_64));}
    static void objectBranches(List<ArmyStrengthsPublicNumbers.Rule> rules,String... paths){for(String path:paths)rules.add(new ArmyStrengthsPublicNumbers.Rule(path,ArmyStrengthsPublicNumbers.Domain.SIGNED_64,ArmyStrengthsPublicNumbers.Traversal.OBJECT_BRANCHES));}
    static void dataRules(List<ArmyStrengthsPublicNumbers.Rule> rules,String p){signed(rules,p+"/records/*/persistent_monthly_replenishment_fraction_raw",p+"/records/*/persistent_prepared_replenishment_fraction_raw");}
    static void rosterRules(List<ArmyStrengthsPublicNumbers.Rule> rules,String p){rules.addAll(ArmyStrengthsRosterPublicRules.publicRules("ArmyCurrentDailyAssaultRosterAdmissionV1",p));}
    static RawJson publicStage(Stage stage,RawJson input){return ArmyStrengthsPublicNumbers.encode(input,stageRules(stage));}
    static List<ArmyStrengthsPublicNumbers.Rule> stageRules(Stage stage){List<ArmyStrengthsPublicNumbers.Rule> r=new ArrayList<>();String p="/*/projection";switch(stage){
        case SAME_INPUT_CURRENT_DAILY_ASSAULT_LOSS_V1->{signed(r,p+"/groups/*/physical_slot_i64",p+"/groups/*/conditional_budget/assault_projection/wrapped_product_raw",p+"/groups/*/conditional_budget/assault_projection/divided_raw");for(String phase:List.of("preferred","residual")){String q=p+"/groups/*/"+phase+"/requests/*";signed(r,q+"/writer_quantity_raw",q+"/writer_projection/writes/*/selected_quantity_raw",q+"/writer_projection/remaining_writer_quantity_raw",q+"/writer_projection/physical_current_delta");}}
        case SAME_INPUT_CURRENT_DAILY_ASSAULT_QUEUE_APPEND_V1->{signed(r,p+"/next_missing_group/physical_slot_i64");objectBranches(r,p+"/missing_inputs/*/next_missing_group/physical_slot_i64");}
        case SAME_INPUT_CURRENT_DAILY_ASSAULT_NORMAL_RETURN_RELEASE_V1->{for(String q:List.of("observed_physical_controls/*/physical_slot_i64","conditional_physical_controls/*/physical_slot_i64","record_release_prefix/*/physical_slot_i64","table_control_count_prefix/*/physical_slot_i64","untouched_captured_group_slots/*","next_missing_record/physical_slot_i64","header_partial_fields/*/physical_slot_i64"))signed(r,p+"/"+q);objectBranches(r,p+"/missing_inputs/*/physical_slot_i64",p+"/queue_missing_inputs/*/next_missing_group/physical_slot_i64");}
        case SAME_INPUT_CURRENT_ASSAULT_FIRST_REMOVAL_V1->{for(String s:List.of("current_pending_selection","conditional_release_pending_selection"))signed(r,p+"/"+s+"/known_invalid_prefix/*/reference/group_physical_slot_i64");}
        case CURRENT_DAILY_ASSAULT_GROUP_INPUTS_V1->{signed(r,"/*/groups/*/physical_slot_i64");objectBranches(r,"/*/missing_inputs/*/physical_slot_i64");}
        case CURRENT_DAILY_ASSAULT_PLACEMENT_INPUTS_V1->signed(r,"/*/groups/*/physical_slot_i64");
        case CURRENT_DAILY_ASSAULT_ROSTER_ADMISSION_INPUTS_V1->r.addAll(ArmyStrengthsRosterPublicRules.publicRules("Projection",p));
        case SAME_QUERY_CONDITIONAL_ASSAULT_GROUP_CONTRIBUTORS_12004->{r.add(new ArmyStrengthsPublicNumbers.Rule(p+"/query_sequence",ArmyStrengthsPublicNumbers.Domain.UNSIGNED_64));String g=p+"/group_budget_outputs/*";signed(r,g+"/physical_slot_i64",g+"/besieging_inputs_v1/assault_context/casualty_percentage_raw");r.addAll(ArmyStrengthsAssault.expectedLossPublicNumberRules(g+"/assault_projection"));dataRules(r,g+"/besieging_inputs_v1/occurrences/*/regiments/*/replenishment_records_v1");}
        default->throw new IllegalArgumentException("not an ASSAULT stage");
    }return List.copyOf(r);}
}
